import PencilKit

/// Compare rendered stroke content rather than archive identifiers regenerated by page splitting.
enum NativeInkChanges {
    static func equal(_ a: PKStroke, _ b: PKStroke) -> Bool {
        guard a.ink.inkType == b.ink.inkType, a.ink.color.isEqual(b.ink.color),
              a.transform == b.transform, a.path.count == b.path.count else { return false }
        if let mask = a.mask { guard mask.isEqual(b.mask) else { return false } }
        else if b.mask != nil { return false }
        return zip(a.path,b.path).allSatisfy { x,y in
            x.location == y.location && x.size == y.size && x.timeOffset == y.timeOffset &&
            x.opacity == y.opacity && x.force == y.force && x.azimuth == y.azimuth &&
            x.altitude == y.altitude && x.secondaryScale == y.secondaryScale
        }
    }
    static func applying(from before: PKDrawing, to after: PKDrawing, onto latest: PKDrawing) -> PKDrawing {
        var removed = before.strokes
        var additions: [(Int,PKStroke)] = []
        for (position,stroke) in after.strokes.enumerated() {
            if let index = removed.firstIndex(where: { equal($0,stroke) }) { removed.remove(at:index) }
            else { additions.append((position,stroke)) }
        }
        var result = latest.strokes
        for stroke in removed {
            if let index = result.firstIndex(where: { equal($0,stroke) }) { result.remove(at:index) }
        }
        for (position,stroke) in additions {
            let anchor = after.strokes.dropFirst(position+1).first { next in result.contains { equal($0,next) } }
            if let anchor, let index = result.firstIndex(where: { equal($0,anchor) }) { result.insert(stroke,at:index) }
            else { result.append(stroke) }
        }
        return PKDrawing(strokes:result)
    }
}

/// One document uses one engine while any of its reader scenes remains open.
/// Switching settings takes effect after the last scene closes, avoiding mixed-format writes.
final class DocumentInkEngineSession {
    private final class WeakSession {
        weak var value: DocumentInkEngineSession?
        init(_ value: DocumentInkEngineSession) { self.value = value }
    }
    private static var sessions: [String:WeakSession] = [:]
    let metal: Bool
    private init(metal: Bool) { self.metal = metal }
    static func acquire(docSha: String, prefersMetal: Bool, containsMetal: () -> Bool) -> DocumentInkEngineSession {
        dispatchPrecondition(condition:.onQueue(.main))
        if let existing = sessions[docSha]?.value { return existing }
        sessions = sessions.filter { $0.value.value != nil }
        let value = DocumentInkEngineSession(metal: prefersMetal || containsMetal())
        sessions[docSha] = WeakSession(value)
        return value
    }
}
